const item = $input.first();
const headers = item.json.headers ?? {};
const binary = item.binary?.data;
const kind = String(headers['x-olivesoft-kind'] ?? '').toLowerCase();
const slug = (s) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 80);
const providedId = slug(String(headers['x-olivesoft-doc-id'] ?? ''));
const originalName = String(headers['x-olivesoft-filename'] ?? binary?.fileName ?? '').split(/[\\/]/).pop() ?? '';
const fileName = originalName.replace(/[^a-zA-Z0-9._ -]/g, '_').slice(0, 120);
const mime = String(headers['content-type'] ?? binary?.mimeType ?? '').split(';')[0].toLowerCase();
const size = Number(headers['content-length'] ?? binary?.fileSize ?? 0);
const validKind = ['cv', 'expertise', 'project'].includes(kind);
const validMime = (fileName.endsWith('.pdf') && mime === 'application/pdf') || (fileName.endsWith('.docx') && mime === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') || ((fileName.endsWith('.txt') || fileName.endsWith('.md')) && (mime === 'text/plain' || mime === 'text/markdown'));
const validName = /\.(pdf|docx|txt|md)$/i.test(fileName);
const extension = fileName.split('.').at(-1).toLowerCase();
const baseName = fileName.slice(0, fileName.length - extension.length - 1);
const docId = providedId || slug(baseName) || 'doc';
const storagePath = `${kind}/${$execution.id}/${fileName}`;
function hash53(str) { let h1 = 0xdeadbeef, h2 = 0x41c6ce57; for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i); h1 = Math.imul(h1 ^ c, 2654435761); h2 = Math.imul(h2 ^ c, 1597334677); } h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909); h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909); return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16); }
const contentHash = `intake:${hash53(`${docId}|${mime}|${size}`)}`;
const valid = Boolean(binary && validKind && validMime && validName && docId && size > 0 && size <= 4194304);
return [{ json: { status: valid ? 'valid' : 'invalid', error: valid ? null : 'Invalid file, category, or size', kind, doc_id: docId, file_name: fileName, mime_type: mime, size, storage_path: storagePath, content_hash: contentHash }, binary: item.binary }];

const stored = $('Upload to Supabase Storage').first().json;
if (!stored.Key) throw new Error('Supabase did not confirm the stored object');
const registered = $('Register document').first().json;
if (!registered.id) throw new Error('Document version conflict: doc_id/version already registered');
const source = $('Validate upload').first().json;
return [{ json: { bucket: 'olivesoft-knowledge', storage_path: source.storage_path, doc_id: source.doc_id, version: registered.version } }];

const upload = $('Validate upload').first();
if (!upload.binary?.data) throw new Error('Validated upload binary is missing');
return [{ json: $input.first().json, binary: upload.binary }];
